@@ -0,0 +1,27 @@
+// Chooses the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+/** The supported language the `Accept-Language` value prefers most (q-values and region tags honored), or `fallback`. */
+export function pickLanguage(acceptLanguage, fallback) {
+  const header = Array.isArray(acceptLanguage) ? acceptLanguage.join(",") : acceptLanguage;
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.split(";").map((s) => s.trim());
+    const lang = tag.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.*)$/i.exec(p);
+      if (m) q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1]) ? Number(m[1]) : 0;
+    }
+    if (q > 0 && (!best || q > best.q)) best = { lang, q };
+  }
+  return best ? best.lang : fallback;
+}
+
+/** The language to answer a request in: its Accept-Language header, else `fallback`. */
+export function requestLanguage(headers, fallback) {
+  const name = Object.keys(headers ?? {}).find((k) => k.toLowerCase() === "accept-language");
+  return pickLanguage(name === undefined ? undefined : headers[name], fallback);
+}
